def walk(o):
    if isinstance(o, dict):
        for k,v in o.items():
            yield from walk(v)
    elif isinstance(o, list):
        for v in o: yield from walk(v)
    elif isinstance(o, str):
        yield o
big = [s for s in walk(r) if len(s) > 300]
