def ratio(files):
    code=0; total=0
    for f in files:
        try: src=open(f).read()
        except: continue
        lines=src.splitlines(); total+=len(lines)
        code_lines=set()
        try:
            for tok in tokenize.generate_tokens(io.StringIO(src).readline):
                if tok.type not in (tokenize.COMMENT, tokenize.NL, tokenize.NEWLINE, tokenize.INDENT, tokenize.DEDENT, tokenize.ENCODING, tokenize.ENDMARKER):
