import re, subprocess, yaml
targets = ['items','item_audit_runs','item_bpc_links','item_taxonomy_links','item_population_elaborations','term_item_links','room_items','case_study_specs','economics_entry_specs','spec_value_probes','probe_population_links','jurisdictional_values','extraction_population_links','citation_population_links','case_study_populations','economics_entry_populations','case_study_outcomes','case_study_strategies','axes','access_need_axis_map','population_axis_map','situations','pipeline_runs','url_verification_runs','v_pmp_latest_walk']
pat = re.compile(r'\b(?:FROM|JOIN|INTO|UPDATE)\s+"?(' + '|'.join(targets) + r')"?\b')
files = subprocess.run("git ls-files 'scripts/*.py' 'scripts/**/*.py' 'tools/*.py' | grep -v migrations/", shell=True, capture_output=True, text=True).stdout.split()
hits = {}
for f in files:
